  ('priya', 92, '15:30', 'Year-end review with Maya', '마야와 연말 평가', 'office_manager', 'rv_priya');
REPLACE INTO messages (id, hero, day, time, kind, sender, subject, subject_ko, body, body_ko) VALUES
  ('r_review_jun', 'jun', 85, '10:00', 'email', 'maya', 'Your 90-day review', '90일 평가 안내', 'Hi Jun, let''s do your 90-day review on Monday, January 4 at 3:30 in my office. I''ll go over your attendance, the team meetings, the work at your desk and how you handled what came up. Nothing to prepare, but bring your questions. Enjoy the holidays!', '준, 90일 평가를 1월 4일 월요일 오후 3시 30분에 내 방에서 해요. 근태, 팀 회의, 자리에서 한 일, 중간에 생긴 일을 어떻게 처리했는지 볼 거예요. 준비할 건 없고, 궁금한 걸 가져와요. 연휴 잘 보내요!'),
  ('r_review_derek', 'derek', 85, '10:00', 'email', 'maya', 'Year-end review', '연말 평가 안내', 'Hi Derek, your year-end review is Monday, January 4 at 3:30 in my office. We''ll look at the year: attendance, meetings, your work and how you handled what came up, plus goals for next year. Enjoy the holidays!', '데릭, 연말 평가는 1월 4일 월요일 오후 3시 30분, 내 방에서 해요. 근태, 회의, 한 일, 중간에 생긴 일을 어떻게 처리했는지 돌아보고 내년 목표도 정해요. 연휴 잘 보내요!'),
  ('r_review_priya', 'priya', 85, '10:00', 'email', 'maya', 'Year-end review', '연말 평가 안내', 'Hi Priya, your year-end review is Monday, January 4 at 3:30 in my office. We''ll look at the year: attendance, meetings, your work and how you handled what came up, plus goals for next year. Enjoy the holidays!', '프리야, 연말 평가는 1월 4일 월요일 오후 3시 30분, 내 방에서 해요. 근태, 회의, 한 일, 중간에 생긴 일을 어떻게 처리했는지 돌아보고 내년 목표도 정해요. 연휴 잘 보내요!');
